BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Section 501(h) expenditure test safe harbor for lobbying
(3, 'Tax-Exempt Organizations', 'Horizon Education Alliance, a 501(c)(3) with exempt-purpose expenditures of $500,000, makes the Section 501(h) election. Under the expenditure test, what is the maximum amount Horizon may spend on lobbying without jeopardizing its exempt status?', '["$100,000 (20% of the first $500,000 of exempt-purpose expenditures)", "$250,000 (50% of exempt-purpose expenditures)", "$50,000 (10% of exempt-purpose expenditures)", "$0 because lobbying is absolutely prohibited for all 501(c)(3) organizations"]'::jsonb, 0, 'Under IRC Section 501(h), the expenditure test allows lobbying up to 20% of the first $500,000 of exempt-purpose expenditures, yielding a $100,000 cap. This provides a specific dollar safe harbor rather than the vague "substantial part" standard. Choice D is wrong because lobbying is permitted within limits — it is political campaign activity, not lobbying, that is absolutely prohibited for 501(c)(3) organizations.', 'medium', 2),

-- Q2: easy / L1 — Dissolution clause requirement
(3, 'Tax-Exempt Organizations', 'What must a 501(c)(3) organization''s governing documents include regarding asset distribution upon dissolution?', '["Assets must be distributed equally among the organization''s members", "Assets must be distributed to another exempt organization or to the government", "Assets must be distributed to the organization''s founders or their heirs", "Assets must be held in trust for five years before any distribution"]'::jsonb, 1, 'Under IRC Section 501(c)(3), the organizational test requires a dissolution clause providing that assets will be distributed to another exempt organization or the government upon dissolution. This ensures assets remain dedicated to exempt purposes. Choice A is wrong because distribution to members would constitute private inurement, violating the prohibition on private benefit to insiders.', 'easy', 1),

-- Q3: medium / L3 — Personal property rent treatment for UBIT (10% threshold)
(3, 'Tax-Exempt Organizations', 'Lakewood Literary Society, a 501(c)(3), leases a building to a commercial tenant for $10,000 per month. The lease also includes office furniture and computer equipment, for which the tenant pays an additional $4,000 per month. How should the personal property rental income be treated for UBIT purposes?', '["All $14,000 per month is excluded from UBIT as passive rental income", "All $14,000 per month is subject to UBIT because the lease includes any personal property", "The $4,000 personal property rent is included in UBIT because it exceeds 10% of total rents under the lease", "Only $1,000 per month is subject to UBIT after applying the specific deduction to each month separately"]'::jsonb, 2, 'Under IRC Section 512(b)(3), rents from real property are generally excluded from UBIT, but rents from personal property are included unless incidental (less than 10% of total rents under the lease). Here, personal property rents are $4,000/$14,000 = 28.6%, well above the 10% threshold. Choice A is wrong because the passive income exclusion for rents applies only to real property rents — personal property rents exceeding the incidental threshold are taxable.', 'medium', 3),

-- Q4: hard / L4 — Supporting organization under Section 509(a)(3)
(3, 'Tax-Exempt Organizations', 'Metro Arts Support Inc. was created to provide fundraising and administrative services exclusively for City Art Museum, a 509(a)(1) public charity. Metro receives 90% of its funding from a single wealthy donor family and channels the funds to City Art Museum. An IRS examiner questions whether Metro qualifies as a supporting organization under Section 509(a)(3). Evaluate Metro''s classification status.', '["Metro is a public charity because it receives substantial funding from public sources", "Metro is a private foundation because it receives more than one-third of support from a single donor", "Metro is a public charity because any organization receiving charitable contributions is automatically publicly supported", "Metro qualifies as a supporting organization under Section 509(a)(3) because it is organized and operated exclusively to support a public charity"]'::jsonb, 3, 'Under IRC Section 509(a)(3), a supporting organization qualifies as a public charity if it is organized and operated exclusively to support one or more public charities, regardless of its funding sources. Metro meets this test by supporting City Art Museum exclusively. Choice B is wrong because the private foundation presumption is rebutted when one of the Section 509(a) exceptions applies — supporting organization status is determined by operational relationship, not by the public support ratio.', 'hard', 4),

-- Q5: medium / L3 — Controlled entity payments (80%+ subsidiary)
(3, 'Tax-Exempt Organizations', 'Hope Medical Foundation, a 501(c)(3), owns 100% of MedServ Inc., a taxable subsidiary. MedServ pays $200,000 in annual rent to Hope for office space. The fair market value of comparable rent is $150,000. How is the rental income treated for UBIT purposes?', '["$50,000 is included in UBIT because it represents the excess above fair market value from a controlled subsidiary", "The entire $200,000 is included in UBIT because all payments from controlled entities are taxable", "All $200,000 is excluded from UBIT because real property rents are passive income regardless of source", "Only $150,000 is included in UBIT because the fair market value portion is the taxable amount"]'::jsonb, 0, 'Under IRC Section 512(b)(13), rent received from a controlled subsidiary (80%+ ownership) is included in UBIT to the extent it exceeds fair market value. The $50,000 excess ($200,000 minus $150,000) is subject to UBIT. Choice C is wrong because the passive income exclusion for real property rents does not apply to payments from controlled entities that exceed fair market value — the controlled entity rule is an exception to the general passive income exclusion.', 'medium', 3),

-- Q6: easy / L1 — Form 990-N (e-Postcard) eligibility threshold
(3, 'Tax-Exempt Organizations', 'Which tax-exempt organizations are eligible to file Form 990-N (e-Postcard)?', '["All 501(c)(3) organizations regardless of size", "Organizations with gross receipts normally $50,000 or less", "Only private foundations with no investment income", "Organizations with gross receipts under $200,000 and total assets under $500,000"]'::jsonb, 1, 'Under IRC Section 6033, organizations with gross receipts normally $50,000 or less may file Form 990-N, an electronic notice providing basic identifying information such as name, address, and EIN. Choice D is wrong because the $200,000/$500,000 thresholds apply to Form 990-EZ eligibility, not Form 990-N — the e-Postcard is reserved for the smallest organizations.', 'easy', 1),

-- Q7: medium / L3 — Bingo games exclusion conditions
(3, 'Tax-Exempt Organizations', 'Riverside Community Center, a 501(c)(3), hosts weekly bingo nights open to the public, charging $20 per card. The organization operates in a jurisdiction where for-profit bingo halls regularly conduct commercial bingo games. Is Riverside''s bingo income excluded from UBIT?', '["Yes, because bingo income is always excluded from UBIT for exempt organizations", "Yes, because the activity is conducted by a 501(c)(3) organization for charitable purposes", "No, because the bingo exclusion does not apply when commercial bingo is ordinarily carried on in the jurisdiction", "No, because charging $20 per card makes the activity a for-profit trade or business by definition"]'::jsonb, 2, 'Under IRC Section 513(f), bingo games are excluded from UBIT only where commercial bingo is not ordinarily carried on in the jurisdiction. Because Riverside operates where for-profit bingo halls exist, the exclusion does not apply. Choice A is wrong because the bingo exclusion is conditional on the absence of competing commercial bingo operations in the jurisdiction, not automatic for all exempt organizations.', 'medium', 3),

-- Q8: medium / L2 — Form 990 filing deadline
(3, 'Tax-Exempt Organizations', 'Goodwill Learning Center, a calendar-year 501(c)(3) organization, wants to determine its Form 990 filing deadline. What is the due date for its annual information return?', '["March 15 of the following year", "April 15 of the following year", "June 15 of the following year", "May 15 of the following year"]'::jsonb, 3, 'Under IRC Section 6033, Form 990 is due on the 15th day of the 5th month after the organization''s tax year ends. For calendar-year organizations, this is May 15. Extensions of up to six months are available using Form 8868. Choice B is wrong because April 15 is the filing deadline for individual income tax returns (Form 1040), not for tax-exempt organization information returns.', 'medium', 2),

-- Q9: medium / L3 — Research exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'State University, a 501(c)(3), conducts three research projects: (1) a $300,000 contract funded by the Department of Defense, (2) a $200,000 project whose results will be freely published and available to the general public, and (3) a $150,000 proprietary study for a pharmaceutical company with results restricted to the sponsor. Which research income is excluded from UBIT?', '["The $300,000 government contract and the $200,000 publicly available research are both excluded", "All three projects are excluded because universities are automatically exempt from UBIT on all research", "Only the $300,000 government contract is excluded; all other research is taxable", "Only the $200,000 publicly available research is excluded from UBIT"]'::jsonb, 0, 'Under IRC Section 512(b)(7)-(9), research performed for the U.S. government and research whose results are freely available to the public are excluded from UBIT. The $150,000 proprietary study does not qualify because results are restricted to the sponsor. Choice B is wrong because the research exclusion is not automatic for universities — proprietary research with restricted results remains subject to UBIT regardless of the institution type.', 'medium', 3),

-- Q10: medium / L2 — One-third support test under Section 509(a)(1)
(3, 'Tax-Exempt Organizations', 'Bright Horizons Charity received 40% of its total support from government grants and public contributions over the past four years. Under Section 509(a)(1), how is Bright Horizons classified?', '["Private foundation because it does not receive more than 50% from public sources", "Public charity because it meets the one-third support test", "Supporting organization because it receives government grants", "Private operating foundation because it actively engages in charitable programs"]'::jsonb, 1, 'Under IRC Section 509(a)(1), an organization qualifies as a public charity if it receives at least one-third (33.3%) of total support from the general public or government sources. Bright Horizons'' 40% exceeds this threshold and satisfies the support test. Choice A is wrong because the threshold is one-third (33.3%), not 50% — there is no majority-support requirement for public charity classification under Section 509(a)(1).', 'medium', 2),

-- Q11: hard / L3 — Convenience exclusion analysis
(3, 'Tax-Exempt Organizations', 'Regional Medical Center, a 501(c)(3) hospital, operates a cafeteria that serves patients, visitors, staff, and the general public from the surrounding neighborhood. The cafeteria is open 12 hours daily, and 35% of sales are to the general public with no connection to the hospital. The CFO claims all cafeteria income is excluded from UBIT under the convenience exclusion. Evaluate this claim.', '["The claim is correct because all hospital cafeteria operations qualify for the convenience exclusion", "The claim is correct because the cafeteria is located on hospital premises", "The claim is partially incorrect because the convenience exclusion applies only to the extent the cafeteria serves patients, their families, and employees — not the general public", "The claim is entirely incorrect because operating a cafeteria is never related to a hospital''s exempt purpose"]'::jsonb, 2, 'Under IRC Section 513(a)(2), the convenience exclusion applies to activities conducted for the convenience of members, students, patients, or employees. Sales to the general public with no hospital connection (35% of sales) do not qualify for this exclusion and are subject to UBIT analysis. Choice A is wrong because the exclusion depends on who is actually being served — routine service to the general public exceeds incidental levels and falls outside the convenience provision.', 'hard', 3),

-- Q12: hard / L4 — Section 4945 taxable expenditure for grant to non-charity without expenditure responsibility
(3, 'Tax-Exempt Organizations', 'The Morrison Family Foundation, a private foundation, makes a $100,000 grant to Community Builders LLC, a for-profit social enterprise, without exercising expenditure responsibility. The foundation''s board believes the grant furthers charitable purposes because Community Builders constructs affordable housing. Analyze the tax consequences under Section 4945.', '["No tax applies because the grant serves a charitable purpose regardless of the recipient''s tax status", "A 10% excise tax applies to the foundation under the self-dealing rules of Section 4941", "A 30% excise tax applies under Section 4942 for failure to distribute to qualifying charities", "A 20% excise tax on the $100,000 expenditure applies because grants to non-charities without expenditure responsibility are taxable expenditures"]'::jsonb, 3, 'Under IRC Section 4945(d)(4), grants by a private foundation to organizations that are not 501(c)(3) public charities are taxable expenditures unless the foundation exercises expenditure responsibility to ensure funds are used for charitable purposes. The 20% initial tax applies on the full $100,000. Choice A is wrong because Section 4945 looks at the recipient''s tax-exempt status and whether expenditure responsibility is exercised, not merely the donor''s charitable intent.', 'hard', 4),

-- Q13: medium / L3 — Rebuttable presumption of reasonableness under Section 4958
(3, 'Tax-Exempt Organizations', 'Evergreen Health Alliance, a 501(c)(3), is setting compensation for its new CEO. The compensation committee consists of three independent board members with no personal relationship to the candidate. The committee reviews salary surveys from five comparable healthcare nonprofits, determines $450,000 is reasonable, and documents its analysis in board minutes. Under Section 4958, what is the effect of these procedures?', '["A rebuttable presumption of reasonableness is established, shifting the burden to the IRS to prove the compensation is excessive", "The compensation is conclusively presumed reasonable and cannot be challenged by the IRS", "The procedures have no legal effect because Section 4958 applies only to private foundations", "The compensation is automatically unreasonable because it exceeds $200,000"]'::jsonb, 0, 'Under IRC Section 4958 and corresponding regulations, the rebuttable presumption of reasonableness arises when compensation is approved by an independent board, supported by appropriate comparability data, and properly documented. This shifts the burden of proof to the IRS. Choice B is wrong because the presumption is rebuttable, not conclusive — the IRS can still challenge the arrangement if it presents sufficient evidence of excess benefit.', 'medium', 3),

-- Q14: easy / L1 — Private inurement prohibition definition
(3, 'Tax-Exempt Organizations', 'What does the private inurement prohibition under Section 501(c)(3) prevent?', '["Tax-exempt organizations from earning any revenue from activities", "Net earnings of the organization from benefiting any private shareholder or individual", "Tax-exempt organizations from hiring paid employees at any salary", "Donors from claiming charitable deductions on their contributions"]'::jsonb, 1, 'Under IRC Section 501(c)(3), the private inurement prohibition prevents any part of an organization''s net earnings from inuring to the benefit of private shareholders or individuals, particularly insiders such as founders, directors, and officers. Choice A is wrong because exempt organizations may earn revenue from multiple sources including unrelated business activities — the prohibition targets improper distribution of earnings to insiders, not revenue generation itself.', 'easy', 1),

-- Q15: medium / L2 — Form 990-PF required for all private foundations
(3, 'Tax-Exempt Organizations', 'Whitfield Family Foundation, a private foundation, has $45,000 in gross receipts and $180,000 in total assets for the year. Which annual return must Whitfield file with the IRS?', '["Form 990-N (e-Postcard) because gross receipts are under $50,000", "Form 990-EZ because gross receipts are under $200,000 and assets are under $500,000", "Form 990-PF because all private foundations must file this form regardless of size", "No filing is required because both gross receipts and total assets are below standard thresholds"]'::jsonb, 2, 'Under IRC Section 6033, all private foundations must file Form 990-PF regardless of their gross receipts or asset levels. The Form 990-PF includes detailed reporting on investments, grants, and excise tax computations specific to private foundations. Choice A is wrong because the Form 990-N eligibility rules do not apply to private foundations — they have a separate mandatory filing requirement under Section 6033(c).', 'medium', 2),

-- Q16: medium / L3 — NOL deduction for UBIT
(3, 'Tax-Exempt Organizations', 'Sunrise Education Foundation, a 501(c)(3), generated $80,000 of unrelated business income and $95,000 of directly connected expenses in 2025, creating a $15,000 net operating loss. In 2026, the foundation earns $60,000 of unrelated business income with $30,000 in expenses. How does the 2025 NOL affect the 2026 UBIT computation?', '["The NOL cannot be carried forward because UBIT does not allow net operating loss deductions for exempt organizations", "The NOL carryforward is disallowed because the 2025 loss resulted entirely from exempt-purpose activities", "The NOL is limited to the $1,000 specific deduction amount, resulting in $28,000 of UBIT", "The $15,000 NOL reduces 2026 UBIT to $14,000 ($60,000 minus $30,000 minus $1,000 specific deduction minus $15,000 NOL carryforward)"]'::jsonb, 3, 'Under IRC Section 512(b)(6), UBIT allows a net operating loss deduction computed using only unrelated business income items. The 2026 computation is: $60,000 gross UBI minus $30,000 expenses minus $1,000 specific deduction minus $15,000 NOL carryforward equals $14,000 taxable UBI. Choice A is wrong because Section 512(b)(6) explicitly permits NOL deductions for UBIT, provided the loss originated from unrelated business activities.', 'medium', 3),

-- Q17: easy / L1 — Churches automatically classified as public charities
(3, 'Tax-Exempt Organizations', 'Under Section 509, which type of 501(c)(3) organization is automatically classified as a public charity regardless of its funding sources?', '["Churches and religious congregations", "Private operating foundations", "Section 501(c)(4) social welfare organizations", "Section 501(c)(6) trade associations"]'::jsonb, 0, 'Under IRC Section 509(a)(1) and Section 170(b)(1)(A)(i), churches are automatically classified as public charities regardless of whether they meet the one-third public support test. This exemption also applies to schools and hospitals. Choice B is wrong because private operating foundations are a subcategory of private foundations with relaxed distribution rules, not public charities.', 'easy', 1),

-- Q18: easy / L1 — Section 4958 initial tax rate on disqualified person (25%)
(3, 'Tax-Exempt Organizations', 'What is the initial excise tax rate imposed on a disqualified person who participates in an excess benefit transaction under Section 4958?', '["10% of the excess benefit", "25% of the excess benefit", "50% of the excess benefit", "200% of the excess benefit"]'::jsonb, 1, 'Under IRC Section 4958(a)(1), the initial excise tax on a disqualified person who receives an excess benefit is 25% of the excess benefit amount. The 200% additional tax applies only if the excess benefit is not corrected within the taxable period. Choice A is wrong because 10% is the tax rate imposed on organization managers who knowingly participate in the transaction, not on the disqualified person receiving the excess benefit.', 'easy', 1),

-- Q19: hard / L4 — Excess business holdings calculation with combined disqualified person holdings
(3, 'Tax-Exempt Organizations', 'Heritage Arts Foundation, a private foundation, owns 12% of the voting stock of Artisan Corp. The foundation''s creator and her family (disqualified persons) own an additional 15% of Artisan Corp.''s voting stock. Under Section 4943, the permitted combined holdings are 20%. The foundation''s investment advisor argues no excise tax applies because the foundation''s 12% alone is below 20%. Evaluate this position.', '["The advisor is correct because Section 4943 measures only the foundation''s direct holdings, not those of disqualified persons", "The advisor is correct because the 20% limit applies separately to the foundation and to disqualified persons", "The advisor is incorrect because the combined holdings of 27% exceed the 20% permitted limit, and the 7% excess is subject to a 10% excise tax", "The advisor is incorrect because any private foundation ownership of voting stock automatically triggers the excess business holdings tax"]'::jsonb, 2, 'Under IRC Section 4943, the permitted combined holdings of a private foundation and its disqualified persons in any business enterprise cannot exceed 20% of voting stock. Heritage''s 12% plus the family''s 15% equals 27%, exceeding the limit by 7%. A 10% initial excise tax applies on the excess holdings. Choice A is wrong because Section 4943 explicitly aggregates foundation and disqualified person holdings when computing excess business holdings.', 'hard', 4),

-- Q20: medium / L2 — Form 990 vs. 990-EZ size thresholds
(3, 'Tax-Exempt Organizations', 'Community Literacy Project, a 501(c)(3), has gross receipts of $185,000 and total assets of $420,000 for the current year. Which annual information return must it file?', '["Form 990-N (e-Postcard) because gross receipts are under $200,000", "Form 990 because total assets exceed $200,000", "No filing is required because both amounts are below the $500,000 asset threshold", "Form 990-EZ because gross receipts are under $200,000 and total assets are under $500,000"]'::jsonb, 3, 'Under IRC Section 6033, organizations with gross receipts under $200,000 AND total assets under $500,000 may file the simplified Form 990-EZ. Community Literacy meets both thresholds ($185,000 and $420,000). Choice B is wrong because Form 990 is required only when gross receipts are $200,000 or more OR total assets are $500,000 or more — neither threshold is met here.', 'medium', 2),

-- Q21: hard / L4 — Multiple private foundation excise taxes operating simultaneously
(3, 'Tax-Exempt Organizations', 'The Keller Foundation, a private foundation, has $8,000,000 in non-charitable-use assets and $600,000 in net investment income. During the year, the foundation distributes only $200,000 for charitable purposes and makes a $50,000 grant to a community development organization that is not a 501(c)(3), without exercising expenditure responsibility. Analyze the combined excise tax consequences.', '["Three excise taxes apply: 1.39% on net investment income (Section 4940), 30% on the $200,000 underdistribution (Section 4942), and 20% on the $50,000 taxable expenditure (Section 4945)", "Only the 1.39% tax on net investment income applies because the foundation made some charitable distributions during the year", "The 30% underdistribution tax and 20% taxable expenditure tax apply, but the net investment income tax is waived when other penalties are assessed", "Only the 20% taxable expenditure tax on the $50,000 grant applies because the grant to a non-charity is the sole violation"]'::jsonb, 0, 'Under IRC Sections 4940, 4942, and 4945, each excise tax operates independently. Section 4940 imposes 1.39% on $600,000 net investment income. Section 4942 imposes 30% on the $200,000 shortfall (5% of $8M = $400,000 required, minus $200,000 distributed). Section 4945 imposes 20% on the $50,000 grant without expenditure responsibility. Choice B is wrong because partial distribution does not eliminate the underdistribution penalty — the full 5% minimum must be met.', 'hard', 4),

-- Q22: easy / L1 — Operational test definition
(3, 'Tax-Exempt Organizations', 'What does the operational test require for Section 501(c)(3) tax-exempt status?', '["The organization must be funded exclusively by government grants and donations", "The organization must be operated primarily for one or more exempt purposes", "The organization must generate no revenue from any commercial source", "The organization must have fewer than 100 employees to maintain exempt status"]'::jsonb, 1, 'Under IRC Section 501(c)(3), the operational test requires that an organization be operated primarily for exempt purposes such as charitable, educational, religious, or scientific activities. This test focuses on actual operations rather than organizational structure. Choice A is wrong because there is no requirement that funding come exclusively from government sources — organizations may earn revenue from multiple sources including program fees and unrelated business activities.', 'easy', 1),

-- Q23: easy / L1 — Form 8868 six-month extension
(3, 'Tax-Exempt Organizations', 'What extension is available for filing Form 990 using Form 8868?', '["A 3-month automatic extension", "A 12-month extension requiring IRS approval", "An automatic 6-month extension", "No extension is available for Form 990 filings"]'::jsonb, 2, 'Under IRC Section 6081, Form 8868 provides an automatic 6-month extension for filing Form 990 and other exempt organization returns. For calendar-year organizations, this extends the deadline from May 15 to November 15. Choice A is wrong because the extension period for exempt organization returns is six months, not three — the three-month extension applies to certain other tax filings such as corporate returns on Form 7004.', 'easy', 1),

-- Q24: medium / L2 — Schedule B confidentiality
(3, 'Tax-Exempt Organizations', 'Meadowbrook Charitable Trust, a 501(c)(3), files its annual Form 990 including Schedule B (Schedule of Contributors). A journalist requests a copy of the organization''s complete Form 990 from the IRS. What information does the journalist receive regarding Schedule B?', '["The complete Schedule B including all contributor names and donation amounts", "Schedule B with contribution amounts visible but all contributor names redacted", "A summary page showing total contributions but no individual donor details", "Schedule B is not publicly available and is not disclosed to the journalist"]'::jsonb, 3, 'Under IRC Section 6104(d)(3)(A), Schedule B (Schedule of Contributors) is confidential and not available for public inspection, even though the rest of Form 990 is publicly accessible. Contributor identities and donation amounts are protected from disclosure. Choice A is wrong because Congress specifically exempted Schedule B from the public disclosure requirements to protect donor privacy and encourage charitable giving.', 'medium', 2),

-- Q25: hard / L4 — Debt-financed income ratio calculation under Section 514
(3, 'Tax-Exempt Organizations', 'Pinnacle Arts Foundation, a 501(c)(3), purchases a commercial building for $1,000,000, financing $700,000 with a mortgage. The building generates $120,000 in annual rental income with $40,000 in deductible expenses. At year-end, the average acquisition indebtedness is $650,000 and the average adjusted basis is $950,000. Calculate the net amount of rental income subject to UBIT under Section 514.', '["$54,737 — the debt/basis percentage (68.4%) applied proportionally to both income and expenses", "$120,000 — all rental income because any mortgage makes the property debt-financed", "$80,000 — all net rental income because debt financing makes the full net amount taxable", "$82,105 — the debt/basis percentage applied to gross income with no proportional expense offset"]'::jsonb, 0, 'Under IRC Section 514, debt-financed income is taxable in proportion to the average acquisition indebtedness divided by average adjusted basis: $650,000/$950,000 = 68.4%. This percentage applies to both income (68.4% x $120,000 = $82,105) and expenses (68.4% x $40,000 = $27,368), yielding net UBIT of $54,737. Choice D is wrong because Section 514 requires proportional allocation of both income and directly connected expenses — the debt/basis ratio reduces deductions as well as income.', 'hard', 4),

-- Q26: medium / L3 — Section 4941 tax on foundation manager (5%)
(3, 'Tax-Exempt Organizations', 'The board president of Carlton Family Foundation, a private foundation, approves the lease of the foundation''s office building to the founder''s daughter at below-market rent. The board president knows the founder''s daughter is a disqualified person and that the transaction constitutes self-dealing under Section 4941. What excise tax applies to the board president?', '["10% of the amount involved, matching the self-dealer''s initial tax rate", "5% of the amount involved for knowingly participating in the self-dealing transaction", "25% of the amount involved as an intermediate sanction under Section 4958", "No tax applies because only the self-dealer is personally liable under Section 4941"]'::jsonb, 1, 'Under IRC Section 4941(a)(2), a foundation manager who knowingly participates in a self-dealing transaction is subject to a 5% excise tax on the amount involved. This is separate from and lower than the 10% initial tax imposed on the self-dealer. Choice D is wrong because Section 4941 imposes separate liability on both the self-dealer (10%) and any foundation manager who knowingly approves the prohibited transaction.', 'medium', 3),

-- Q27: medium / L2 — Failure-to-file penalty ($20/day)
(3, 'Tax-Exempt Organizations', 'Neighborhood Youth Alliance, a 501(c)(3) with $800,000 in annual gross receipts, files its Form 990 forty-five days late without an extension. What penalty does the organization face?', '["$500 flat penalty for late filing of an information return", "$45 per day for 45 days, totaling $2,025", "$20 per day for 45 days, totaling $900", "5% of gross receipts ($40,000) as a mandatory late-filing penalty"]'::jsonb, 2, 'Under IRC Section 6652(c)(1)(A), the penalty for late filing of Form 990 by organizations with gross receipts under $1,186,000 is $20 per day, up to the lesser of $10,500 or 5% of gross receipts. For 45 days, the penalty is $900 (45 x $20). Choice D is wrong because 5% of gross receipts ($40,000) represents the maximum penalty cap for this size organization, not the actual penalty calculated at the per-day rate.', 'medium', 2),

-- Q28: easy / L1 — Form 990-T filing threshold ($1,000 gross UBI)
(3, 'Tax-Exempt Organizations', 'What is the gross unrelated business income threshold that triggers a Form 990-T filing requirement for a tax-exempt organization?', '["$500 or more in gross unrelated business income", "$5,000 or more in gross unrelated business income", "$10,000 or more in gross unrelated business income", "$1,000 or more in gross unrelated business income"]'::jsonb, 3, 'Under IRC Section 6012(a)(4), a tax-exempt organization must file Form 990-T if it has gross unrelated business income of $1,000 or more. This threshold applies to gross income before expenses and the $1,000 specific deduction. Choice A is wrong because $500 is not a threshold used in the UBIT filing requirements — the $1,000 threshold aligns with the specific deduction that effectively exempts the first $1,000 of UBI from tax.', 'easy', 1),

-- Q29: medium / L2 — Section 509(a)(2) gross receipts test
(3, 'Tax-Exempt Organizations', 'Coastal Marine Research Institute, a 501(c)(3), receives 40% of its support from admission fees and program revenue related to its marine education mission, 25% from public contributions, 20% from government grants, and 15% from investment income. Under Section 509(a)(2), does the institute qualify as a public charity?', '["Yes, because more than one-third of support comes from contributions, fees, and related activity receipts, and investment income does not exceed one-third", "No, because the organization receives investment income from nonexempt sources", "No, because program service revenue cannot be counted toward the public support test under Section 509(a)(2)", "Yes, but only if it also satisfies the one-third support test under Section 509(a)(1)"]'::jsonb, 0, 'Under IRC Section 509(a)(2), an organization qualifies as a public charity if more than one-third of its support comes from contributions, membership fees, and gross receipts from related activities, and no more than one-third comes from gross investment income. Here, qualifying support is 85% (40% + 25% + 20%) and investment income is only 15%. Choice C is wrong because Section 509(a)(2) specifically includes gross receipts from activities related to exempt functions as qualifying support.', 'medium', 2),

-- Q30: easy / L2 — Default presumption as private foundation
(3, 'Tax-Exempt Organizations', 'Global Health Initiative, a newly recognized 501(c)(3) organization, has not yet established its public funding base. How is this organization initially classified under Section 509?', '["As a public charity until the IRS determines otherwise based on funding sources", "As a private foundation, because all 501(c)(3) organizations are presumed to be private foundations unless they demonstrate public charity status", "As a supporting organization until it receives sufficient public donations", "As a tax-exempt social welfare organization under Section 501(c)(4)"]'::jsonb, 1, 'Under IRC Section 509(a), all 501(c)(3) organizations are presumed to be private foundations unless they can demonstrate they qualify as a public charity under one of the Section 509(a) exceptions. This presumption places the burden of proof on the organization. Choice A is wrong because the default classification is private foundation, not public charity — the organization must affirmatively establish that it meets a public charity test to overcome the presumption.', 'easy', 2)
;

COMMIT;
